import time

class BotnetSimulator:
    def __init__(self, num_bots):
        self.num_bots = num_bots
        self.wallets = [self.generate_wallet() for _ in range(num_bots)]

    def generate_wallet(self):
        return ''.join(random.choices('abcdefghijklmnopqrstuvwxyz0123456789', k=34))

    def simulate_transaction(self):
        sender = random.choice(self.wallets)
        receiver = random.choice(self.wallets)
        amount = round(random.uniform(0.001, 5.0), 8)
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.gmtime())
        return {
            'sender': sender,
            'receiver': receiver,
            'amount': amount,
            'timestamp': timestamp
        }

    def run_simulation(self, duration):
        start_time = time.time()
        transactions = []
        while time.time() - start_time < duration:
            transactions.append(self.simulate_transaction())
            time.sleep(random.uniform(0.01, 0.1))  # Simulate network latency
        return transactions

